10-15T07:32:35.374Z","observedAt":"2026-10-15T05:32:35.374Z","sourceVersion":"POS_SNAPSHOT:2026-10-15T05:32:35.374Z"},"schemaVersion":1,"scope":{"kind":"PRODUCT","productId":"SV2447","variantId":"offer:SV2447:SET_VAY"},"type":"STOCK","value":{"availableQuantity":58,"status":"IN_STOCK"}}],"runtimeProducts":[{"content":{"description":"Thiết kế nữ tính và nhẹ nhàng với chất liệu thô đũi thêu hoa nổi, mang lại cảm giác mềm mại, thoáng mát và dễ chịu khi mặc. Bề mặt vải được thêu họa tiết hoa tinh tế, tạo điểm nhấn nổi bật nhưng vẫn giữ được nét thanh lịch. Áo được thiết kế dáng xếp nhún thân, giúp tạo độ bồng nhẹ và tôn dáng mềm mại. Phần chân áo thêu 2 tầng mang lại hiệu ứng bay nhẹ, giúp tổng thể trang phục thêm phần duyên dáng. Thiết kế dây buộc có thể điều chỉnh, giúp nàng dễ dàng tùy chỉnh độ ôm phù hợp với dáng người, mang lại cảm giác thoải mái khi mặc.","metadata":{"authority":"WEBSTORE_XML","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"productName":"Set quần Như Sa","productUrl":null},"ref":"product:SQ123","subjectRef":"SQ123"},{"content":{"description":"Thiết kế trẻ trung và nữ tính với chất liệu vải thô đục lỗ in họa tiết hoa, mang lại cảm giác thoáng mát, nhẹ và đứng form đẹp khi mặc. Bề mặt vải được phối dây ren tinh tế, tạo điểm nhấn mềm mại và giúp tổng thể trang phục trở nên nổi bật hơn. Áo được thiết kế 1 lớp form gọn gàng, chất liệu đứng form giúp tôn dáng và mang lại vẻ ngoài thanh lịch nhưng vẫn trẻ trung. Họa tiết hoa kết hợp chi tiết ren tạo nên phong cách nhẹ nhàng và nữ tính. Phối cùng quần 2 lớp cạp chun, thiết kế thoải mái và dễ mặc, phù hợp với nhiều dáng người. Form quần gọn gàng giúp tổng thể set đồ trở nên năng động nhưng vẫn giữ được nét tinh tế.","metadata":{"authority":"WEBSTORE_XML","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"productName":"Set quần Xuân Thảo","productUrl":null},"ref":"product:SQ223","subjectRef":"SQ223"},{"content":{"description":"Thiết kế nữ tính, nhẹ nhàng với chất liệu thô boi phối ren cho cả áo và chân váy, mang lại cảm giác thoáng mát, mềm nhẹ và dễ chịu khi mặc. Sự kết hợp giữa chất vải thô mộc mạc và ren tinh tế tạo nên tổng thể hài hòa, vừa gần gũi vừa thanh lịch. Áo được thiết kế form suông nhẹ, dễ mặc và phù hợp với nhiều dáng người. Các chi tiết phối ren tinh tế giúp tạo điểm nhấn mềm mại, tăng thêm nét nữ tính cho trang phục. Chân váy được làm từ thô boi phối ren, form váy nhẹ nhàng với độ rũ tự nhiên. Thiết kế cạp chun linh hoạt, giúp mặc thoải mái và dễ dàng, phù hợp với nhiều vóc dáng. Phần ren được xử lý khéo léo, tạo độ bay nhẹ và tăng tính thẩm mỹ cho tổng thể.","metadata":{"authority":"WEBSTORE_XML","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"productName":"Set váy Khánh Trang","productUrl":null},"ref":"product:SV1561","subjectRef":"SV1561"},{"content":{"description":"Thiết kế nữ tính và nổi bật với sự kết hợp giữa tơ Hàn thêu cao cấp và ren tơ Hàn mềm mại, mang lại cảm giác nhẹ nhàng, bay bổng và tinh tế khi mặc. Bề mặt vải được xử lý tỉ mỉ với các họa tiết thêu nổi, tạo điểm nhấn sang trọng và cuốn hút. Áo được thiết kế từ tơ Hàn thêu, form nhẹ nhàng giúp tôn dáng thanh thoát. Chất vải mềm, thoáng và có độ bay tự nhiên, mang lại sự thoải mái khi mặc. Các chi tiết thêu được hoàn thiện tinh xảo, giúp tổng thể trở nên nổi bật nhưng vẫn giữ được nét dịu dàng. Váy được làm từ ren tơ Hàn, tạo hiệu ứng mềm mại và nữ tính. Form váy nhẹ nhàng với độ rũ tự nhiên, giúp tôn dáng và tạo chuyển động uyển chuyển khi di chuyển. Sự kết hợp giữa áo thêu tinh tế và chân váy ren bay bổng mang đến tổng thể hài hòa, phù hợp cho nhiều phong cách từ nhẹ nhàng đến sang trọng.","metadata":{"authority":"WEBSTORE_XML","expiresAt":null,"freshForSeconds":null,"freshnessState":"FRESH","observedAt":"2026-09-28T04:31:05.725Z","sourceVersion":"catalog-v2"},"productName":"Set váy Thạch Thảo","productUrl":null},"ref":"product:SV2447","subjectRef":"SV2447"}],"state":{"bindingVersion":"c3-b1-source-v1","conversationOwner":"BOT","currentProductId":null,"factSnapshotVersion":"6e52f2fe6956b91a2f49c2328e10e6ab8986dcfbc23a674a7bb9095f71e2d75a","permission":true,"privacyAllowed":true,"recipient":"b27201293c0a1a7fe3a7c3a8db4c7278eee3ffd179b783ca948c9cf4027cd20f","revision":1}},"untrusted":{"latestCustomerMessage":"Chị phải lên sân khấu có đèn rọi thẳng, chị ngại thấy bóng áo lót. Vậy còn nên lấy set này không?","recentAcceptedDialogue":[{"role":"customer","text":"Chị đang xem set Thạch Thảo SV2447 để đi tiệc trong nhà."},{"role":"shop","text":"Set này có thể mặc đi tiệc chị nhé."}],"finalDraft":"Với việc phải lên sân khấu có đèn rọi thẳng, **em chưa khuyên chị chốt set Thạch Thảo** nếu ưu tiên là không thấy bóng áo lót. Lúc nãy em mới xét về kiểu dáng đi tiệc, chưa tính điều kiện ánh sáng này.

Áo là tơ Hàn thêu, nhưng thông tin hiện có chưa xác nhận lớp lót hay độ che phủ dưới đèn mạnh, nên em không thể bảo đảm áo kín trong hoàn cảnh của chị.

Nếu chị vẫn thích set này, nên thử cùng nội y màu gần da, bề mặt trơn dưới ánh sáng tương tự sân khấu trước khi quyết định; cách phối đó chỉ giúp hạn chế lộ, không bảo đảm hết bóng. Nếu không có điều kiện thử, em nghiêng về chọn áo có lớp lót kín đã được xác nhận hơn là lấy set này cho buổi tiệc đó ạ."}}

